-- Grade 8 English (2024 revised KICD): factual thematic outline, official source link,
-- and independently authored VibeSchool teaching guidance. NOT official KICD outcome text.
-- No teacher records, timetable, or school calendar entries are inserted here.
-- Existing Grade 8 English placeholder records are never deleted or overwritten.
begin;
-- authorization-test: public.grade8_english_reader_bindings
create table if not exists public.grade8_english_reader_bindings (
  source_ref text primary key check(source_ref like 'VS-CUR-G08-EN-2026#%'),
  sub_strand_id uuid not null unique references public.cbc_strands(id) on delete restrict,
  source_url text not null,
  source_version text not null,
  key_inquiry_questions text[] not null default '{}',
  suggested_experiences text[] not null default '{}',
  status text not null default 'active' check(status in ('active','archived')),
  created_at timestamptz not null default now()
);
alter table public.grade8_english_reader_bindings enable row level security;
revoke all on public.grade8_english_reader_bindings from public,anon,authenticated;
grant select on public.grade8_english_reader_bindings to authenticated;
drop policy if exists grade8_english_bindings_read on public.grade8_english_reader_bindings;
create policy grade8_english_bindings_read on public.grade8_english_reader_bindings
 for select to authenticated using(status='active');

create temporary table _vs_g8_english_catalog(source_ref text primary key,unit jsonb not null) on commit drop;
insert into _vs_g8_english_catalog(source_ref,unit)
select 'VS-CUR-G08-EN-2026#'||(unit->>'id'),unit
